import java.util.*;
import java.io.*;

public class Main {
    static final int MOD = 1000000007;
    static int n;
    static int S;
    static int[] cnt = new int[250];
    static int[] id = new int[250];
    static int[][] f = new int[10][250];
    static List<Integer>[] vec = new ArrayList[10];
    static Map<Pair, Integer> mp = new HashMap<>();

    static {
        for (int i = 0; i < 10; i++) {
            vec[i] = new ArrayList<>();
        }
    }

    static class Pair {
        int x;
        long state;

        Pair(int x, long state) {
            this.x = x;
            this.state = state;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Pair)) return false;
            Pair pair = (Pair) o;
            return x == pair.x && state == pair.state;
        }

        @Override
        public int hashCode() {
            return Objects.hash(x, state);
        }
    }

    static int power(int base, int exp) {
        long result = 1;
        long b = base;
        long e = exp;
        while (e > 0) {
            if ((e & 1) == 1) {
                result = (result * b) % MOD;
            }
            b = (b * b) % MOD;
            e >>= 1;
        }
        return (int) result;
    }

    static int DP(int x, long state) {
        if (state == 0) return 0;
        if (x == n) return 1;
        Pair key = new Pair(x, state);
        if (mp.containsKey(key)) return mp.get(key);

        S++;
        int answer = 0;
        int limit = (1 << n) - 1;
        for (int j = 1; j <= limit; j++) {
            long next_state = 0;
            for (int kIdx = 0; kIdx < vec[x].size(); kIdx++) {
                int las = vec[x].get(kIdx);
                if ((state & (1L << kIdx)) == 0) continue;
                for (int l = 0; l < n; l++) {
                    if ((j & (1 << l)) != 0 && (las & (1 << l)) == 0) {
                        next_state |= 1L << id[las | (1 << l)];
                    }
                }
            }
            long temp = ((long)f[x][j] * DP(x + 1, next_state)) % MOD;
            answer = (answer + (int) temp) % MOD;
        }
        mp.put(key, answer);
        return answer;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        n = Integer.parseInt(br.readLine());
        int inv100 = power(100, MOD - 2);
        for (int i = 0; i < n; i++) {
            Arrays.fill(f[i], 1);
            String[] P_str = br.readLine().split(" ");
            for (int j = 0; j < n; j++) {
                int P = Integer.parseInt(P_str[j]);
                int p1 = (int) ((long) P * inv100 % MOD);
                int p0 = (MOD + 1 - p1) % MOD;
                for (int k = (1 << j) - 1; k >= 0; k--) {
                    f[i][k | (1 << j)] = (int) ((long)f[i][k] * p1 % MOD);
                    f[i][k] = (int) ((long)f[i][k] * p0 % MOD);
                }
            }
        }
        for (int i = 0; i < (1 << n); i++) {
            cnt[i] = Integer.bitCount(i);
        }
        for (int i = 0; i < (1 << n); i++) {
            vec[cnt[i]].add(i);
            id[i] = vec[cnt[i]].size() - 1;
        }
        System.out.println(DP(0, 1L));
    }
}
